package com.astra.tvhome;

import android.content.pm.*;
import android.os.*;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.util.regex.*;

/** Explicit plans and per-operation journals. Core packages and the original launcher are never disabled. */
final class Maintenance implements AutoCloseable {
    interface Work<T>{T get()throws Exception;}
    final MainActivity a;final TvAdb adb;final ExecutorService worker=Executors.newSingleThreadExecutor();
    volatile boolean busy;volatile String progress="";final File records;String originalHome="";
    static final String PACKAGE="[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)+";
    static final Set<String> CORE=new HashSet<>(Arrays.asList("android","com.android.systemui","com.android.shell","com.android.settings","com.android.tv.settings","com.android.phone","com.android.bluetooth","com.android.networkstack","com.android.networkstack.permissionconfig","com.android.providers.settings","com.android.providers.downloads","com.android.packageinstaller","com.google.android.packageinstaller","com.android.permissioncontroller","com.google.android.permissioncontroller","com.android.ext.services","com.android.ext.shared","com.android.modulemetadata","com.google.android.ext.services","com.google.android.modulemetadata","com.astra.tvhome"));
    static final class Item {String pkg,label,category,evidence;boolean enabled,protectedItem;Item(String p,String l,String c,String e,boolean on,boolean guard){pkg=p;label=l;category=c;evidence=e;enabled=on;protectedItem=guard;}}
    Maintenance(MainActivity a){this.a=a;adb=new TvAdb(a);records=new File(a.getFilesDir(),"maintenance-records");records.mkdirs();originalHome=a.pref().getString("originalHome","");}
    <T> void run(String title,Work<T> work,Consumer<T> done){if(busy){a.toast("正在处理，请稍候");return;}busy=true;progress=title;a.toast(title);worker.execute(()->{try{T value=work.get();a.runOnUiThread(()->{busy=false;progress="";done.accept(value);});}catch(Exception e){a.runOnUiThread(()->{busy=false;progress="";a.panels.message("操作未完成",e.getMessage()==null?e.toString():e.getMessage());a.panels.backAction=()->a.panels.maintenance();});}});}
    static byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[8192];for(int n;(n=in.read(block))!=-1;){if(out.size()+n>8388608)throw new IOException("文件超过 8 MB 限制");out.write(block,0,n);}return out.toByteArray();}
    static void packageName(String pkg){if("android".equals(pkg))return;if(pkg==null||!pkg.matches(PACKAGE))throw new IllegalArgumentException("无效应用包名");}
    boolean protectedPackage(String pkg){
        packageName(pkg);if(CORE.contains(pkg)||pkg.equals(a.getPackageName()))return true;
        if(pkg.startsWith("com.android.providers.")||pkg.startsWith("com.google.android.overlay.modules")||pkg.matches(".*(permissioncontroller|packageinstaller|networkstack|tethering|bluetooth|tvinput|hdmi|camera|usb|systemui).*"))return true;
        try{PackageInfo info=a.getPackageManager().getPackageInfo(pkg,PackageManager.GET_PERMISSIONS);if(info.requestedPermissions!=null)for(String permission:info.requestedPermissions)if(permission.equals("android.permission.TV_INPUT_HARDWARE")||permission.equals("android.permission.MAINLINE_NETWORK_STACK"))return true;}catch(PackageManager.NameNotFoundException ignored){}
        String homePkg=originalHome.isEmpty()?"com.mitv.tvhome":originalHome.split("/")[0];return pkg.equals(homePkg)||pkg.equals("com.google.android.tungsten.setupwraith")||pkg.matches(".*(mitv.tvhome|mitv.settings|mitv.tvmanager|mitv.remote|mitv.input).*" );
    }
    List<Item> inventory(String category)throws Exception{
        Map<String,JSONObject> catalog=new HashMap<>();try(InputStream in=a.getAssets().open("cleanup-catalog.json")){JSONArray entries=new JSONArray(new String(readAll(in),StandardCharsets.UTF_8));for(int i=0;i<entries.length();i++){JSONObject entry=entries.getJSONObject(i);catalog.put(entry.getString("package"),entry);}}catch(FileNotFoundException ignored){}
        ArrayList<Item> out=new ArrayList<>();PackageManager pm=a.getPackageManager();
        for(ApplicationInfo info:pm.getInstalledApplications(PackageManager.GET_DISABLED_COMPONENTS)){
            String pkg=info.packageName;JSONObject known=catalog.get(pkg);String kind="",evidence="";
            if(pkg.matches(".*(analytics|telemetry|inscape|acrservice|statistic|usagelog).*")){kind="隐私与统计";evidence=known==null?"仅包名匹配，需要核对功能；不代表正在采集":known.optString("evidence","社区隐私组件记录");}
            else if(TvSystem.ADS.contains(pkg)){kind="广告与推荐";evidence="小米社区记录中的广告 / 推荐候选组件";}
            else if(known!=null){kind=known.optString("category","预装应用");evidence=known.optString("evidence","CleanYourTV 社区清单");}
            else if((info.flags&ApplicationInfo.FLAG_SYSTEM)!=0){kind="预装应用";evidence="系统预装；功能与依赖需要核对";}
            else {kind="已安装应用";evidence="用户安装的应用";}
            if(!category.equals("全部组件")&&!category.equals(kind))continue;
            out.add(new Item(pkg,pm.getApplicationLabel(info).toString(),kind,evidence,info.enabled,protectedPackage(pkg)));
        }
        out.sort(Comparator.comparing((Item i)->i.protectedItem).thenComparing(i->i.label));return out;
    }
    String home()throws Exception{String value=adb.shell("cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME").trim();for(String line:value.split("\\n"))if(line.matches("[A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+"))return line;throw new IOException("无法确定当前原桌面，停止操作");}
    JSONObject identity()throws Exception{return new JSONObject().put("model",Build.MODEL).put("device",Build.DEVICE).put("fingerprint",adb.shell("getprop ro.build.fingerprint").trim());}
    void validateIdentity(JSONObject record)throws Exception{JSONObject id=record.getJSONObject("device");if(!Build.FINGERPRINT.equals(id.getString("fingerprint"))||!Build.DEVICE.equals(id.getString("device"))||!adb.fingerprint.equals(id.getString("fingerprint")))throw new IOException("备份不属于当前电视固件，无法执行");}
    JSONObject newRecord(String type)throws Exception{JSONObject record=new JSONObject().put("schema",1).put("id",new SimpleDateFormat("yyyyMMdd-HHmmss-SSS",Locale.ROOT).format(new Date())).put("type",type).put("device",identity()).put("homeBefore",home()).put("status","prepared").put("operations",new JSONArray()).put("createdAt",System.currentTimeMillis());if(originalHome.isEmpty()){originalHome=record.getString("homeBefore");a.pref().edit().putString("originalHome",originalHome).apply();}return record;}
    int state(String pkg)throws Exception{packageName(pkg);String dump=adb.shell("dumpsys package "+pkg);Matcher m=Pattern.compile("User 0:.*?enabled=(\\d+)").matcher(dump);if(!m.find())throw new IOException("无法读取应用原始状态："+pkg);int value=Integer.parseInt(m.group(1));if(value<0||value>4)throw new IOException("应用状态不受支持："+pkg);return value;}
    static String stateCommand(String pkg,int state){packageName(pkg);String verb=switch(state){case 0->"default-state";case 1->"enable";case 2->"disable";case 3->"disable-user";case 4->"disable-until-used";default->throw new IllegalArgumentException("无效原始状态");};return "pm "+verb+" --user 0 "+pkg;}
    void save(JSONObject record)throws Exception{AtomicFile file=new AtomicFile(new File(records,record.getString("id")+".json"));FileOutputStream stream=file.startWrite();try{stream.write(record.toString(2).getBytes(StandardCharsets.UTF_8));file.finishWrite(stream);}catch(Exception e){file.failWrite(stream);throw e;}}
    void export(JSONObject record)throws Exception{String dir="/sdcard/Download/AstraTV-Recovery/"+record.getString("id");adb.shell("mkdir -p "+TvAdb.quote(dir));adb.push(record.toString(2).getBytes(StandardCharsets.UTF_8),dir+"/record.json");StringBuilder restore=new StringBuilder("#!/system/bin/sh\n# ASTRA recovery: verify the same device and firmware before running.\n");restore.append("[ \"$(getprop ro.build.fingerprint)\" = ").append(TvAdb.quote(record.getJSONObject("device").getString("fingerprint"))).append(" ] || exit 1\n");JSONArray ops=record.getJSONArray("operations");for(int i=ops.length()-1;i>=0;i--){JSONObject op=ops.getJSONObject(i);if(op.getString("kind").equals("package"))restore.append(stateCommand(op.getString("package"),op.getInt("before"))).append('\n');else if(op.getString("kind").equals("dns")){restore.append(settingRestore("private_dns_mode",op.optString("modeBefore","null"))).append('\n');restore.append(settingRestore("private_dns_specifier",op.optString("hostBefore","null"))).append('\n');}else if(op.getString("kind").equals("home"))restore.append("cmd package set-home-activity --user 0 ").append(TvAdb.quote(op.getString("before"))).append('\n');}adb.push(restore.toString().getBytes(StandardCharsets.UTF_8),dir+"/restore.sh");}
    JSONObject snapshot()throws Exception{JSONObject record=newRecord("snapshot");record.put("packages",adb.shell("pm list packages -f -u")).put("disabled",adb.shell("pm list packages -d")).put("settingsGlobal",adb.shell("settings list global")).put("settingsSecure",adb.shell("settings list secure")).put("settingsSystem",adb.shell("settings list system")).put("status","snapshot");save(record);return record;}
    JSONObject disable(Collection<String> selected)throws Exception{return changePackages(selected,3);}
    JSONObject changePackages(Collection<String> selected,int desired)throws Exception{
        if(desired!=0&&desired!=1&&desired!=3)throw new IOException("不支持的目标状态");
        if(selected.isEmpty())throw new IOException("请先选择组件");JSONObject record=newRecord("packages");JSONArray ops=record.getJSONArray("operations");
        for(String pkg:selected){if(protectedPackage(pkg))throw new IOException("受保护组件不能停用："+pkg);int before=state(pkg);if(before==desired||(desired==3&&before>=2))continue;ops.put(new JSONObject().put("kind","package").put("package",pkg).put("before",before).put("after",desired).put("status","pending"));}
        if(ops.length()==0)throw new IOException("所选组件已处于目标状态，无需重复修改");save(record);export(record);
        try{for(int i=0;i<ops.length();i++){JSONObject op=ops.getJSONObject(i);op.put("status","applying");save(record);adb.shell(stateCommand(op.getString("package"),desired));if(state(op.getString("package"))!=desired)throw new IOException("电视未应用停用状态");op.put("status","applied");save(record);}record.put("status","applied");save(record);export(record);return record;}
        catch(Exception failure){record.put("status","partial").put("error",failure.getMessage());save(record);try{export(record);}catch(Exception ignored){}throw new IOException("操作中止，已保存部分执行记录。请到恢复中心查看。\\n"+failure.getMessage());}
    }
    JSONObject restore(JSONObject record)throws Exception{validateIdentity(record);JSONArray ops=record.getJSONArray("operations");for(int i=ops.length()-1;i>=0;i--){JSONObject op=ops.getJSONObject(i);String status=op.optString("status");if(status.equals("pending")||status.equals("restored"))continue;String kind=op.getString("kind");if(kind.equals("package")){String pkg=op.getString("package");if(protectedPackage(pkg))throw new IOException("恢复记录包含受保护组件，已停止");adb.shell(stateCommand(pkg,op.getInt("before")));if(state(pkg)!=op.getInt("before"))throw new IOException("恢复核验失败："+pkg);}else if(kind.equals("dns")){adb.shell(settingRestore("private_dns_mode",op.optString("modeBefore","null")));adb.shell(settingRestore("private_dns_specifier",op.optString("hostBefore","null")));if(!adb.shell("settings get global private_dns_mode").trim().equals(op.optString("modeBefore","null"))||!adb.shell("settings get global private_dns_specifier").trim().equals(op.optString("hostBefore","null")))throw new IOException("DNS 恢复核验失败");}else if(kind.equals("home")){String before=op.getString("before");component(before);adb.shell("cmd package set-home-activity --user 0 "+TvAdb.quote(before));if(!home().equals(before))throw new IOException("原桌面恢复核验失败");}else throw new IOException("未知恢复操作");op.put("status","restored");save(record);}record.put("status","restored");save(record);export(record);return record;}
    static String settingRestore(String key,String value){if(!key.equals("private_dns_mode")&&!key.equals("private_dns_specifier"))throw new IllegalArgumentException("不支持的设置项");return value.equals("null")?"settings delete global "+key:"settings put global "+key+" "+TvAdb.quote(value);}
    JSONObject dns(String mode,String host)throws Exception{if(!Arrays.asList("off","opportunistic","hostname").contains(mode))throw new IOException("DNS 模式不受支持");if(mode.equals("hostname")&&!host.matches("(?=.{1,253}$)[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\\.[A-Za-z]{2,}"))throw new IOException("请输入有效的 DNS 主机名");JSONObject record=newRecord("dns");JSONObject op=new JSONObject().put("kind","dns").put("modeBefore",adb.shell("settings get global private_dns_mode").trim()).put("hostBefore",adb.shell("settings get global private_dns_specifier").trim()).put("modeAfter",mode).put("hostAfter",host).put("status","applying");record.getJSONArray("operations").put(op);save(record);export(record);try{adb.shell("settings put global private_dns_specifier "+TvAdb.quote(host));adb.shell("settings put global private_dns_mode "+mode);if(!adb.shell("settings get global private_dns_mode").trim().equals(mode)||!adb.shell("settings get global private_dns_specifier").trim().equals(host))throw new IOException("DNS 设置核验失败");op.put("status","applied");record.put("status","applied");save(record);export(record);return record;}catch(Exception e){record.put("status","partial");save(record);throw e;}}
    static void component(String value)throws IOException{if(!value.matches("[A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+"))throw new IOException("无效桌面组件");}
    JSONObject setHome(boolean astra)throws Exception{JSONObject record=newRecord("home");String target=astra?"com.astra.tvhome/.MainActivity":a.pref().getString("originalHome","com.mitv.tvhome/.MainActivityUserMode");component(target);JSONObject op=new JSONObject().put("kind","home").put("before",record.getString("homeBefore")).put("after",target).put("status","applying");record.getJSONArray("operations").put(op);save(record);export(record);adb.shell("cmd package set-home-activity --user 0 "+TvAdb.quote(target));if(!home().equals(target))throw new IOException("电视未接受默认桌面设置，原桌面应用仍保留");op.put("status","applied");record.put("status","applied");save(record);export(record);return record;}
    List<JSONObject> history()throws Exception{ArrayList<JSONObject> list=new ArrayList<>();File[] files=records.listFiles((d,n)->n.endsWith(".json"));if(files!=null){Arrays.sort(files,Comparator.comparing(File::getName).reversed());for(File file:files)try(FileInputStream in=new FileInputStream(file)){JSONObject record=new JSONObject(new String(readAll(in),StandardCharsets.UTF_8));if(!record.optBoolean("testOnly",false))list.add(record);}}return list;}
    String drift()throws Exception{StringBuilder text=new StringBuilder("当前固件：\n"+Build.FINGERPRINT+"\n\n");int checks=0,changed=0;Set<String> seen=new HashSet<>();for(JSONObject record:history()){if(record.optString("status").equals("restored"))continue;if(!record.getJSONObject("device").optString("fingerprint").equals(Build.FINGERPRINT)){text.append("发现其他固件的记录；请重新核对清单，旧记录不会直接执行。\n");continue;}JSONArray ops=record.getJSONArray("operations");for(int i=ops.length()-1;i>=0;i--){JSONObject op=ops.getJSONObject(i);if(!op.optString("kind").equals("package")||!op.optString("status").equals("applied"))continue;String pkg=op.getString("package");if(!seen.add(pkg))continue;checks++;try{int actual=state(pkg);if(actual!=op.getInt("after")){changed++;text.append(pkg).append("：预期 ").append(op.getInt("after")).append("，实际 ").append(actual).append('\n');}}catch(Exception e){text.append(pkg).append("：无法读取当前状态\n");changed++;}}}text.append("\n已核对 ").append(checks).append(" 个组件，发现 ").append(changed).append(" 处变化。\n当前 HOME：").append(home()).append("\n\n如需重新清理，请回到组件清单选择并预览新的方案。");return text.toString();}
    String privacy()throws Exception{StringBuilder text=new StringBuilder("只读检查；权限或 AppOps 允许不代表正在录音。\\n\\n");String recognizer=adb.shell("settings get secure voice_recognition_service");text.append("系统语音识别服务：").append(recognizer).append("\\n\\n");for(Item item:inventory("全部组件"))if(item.pkg.matches(".*(voice|speech|katniss|assistant|analytics|telemetry|inscape|acr|misight).*")){String ops=adb.shell("cmd appops get "+item.pkg+" RECORD_AUDIO 2>/dev/null || true");text.append(item.label).append("\\n").append(item.pkg).append("\\n").append(ops.isEmpty()?"未返回麦克风访问记录":ops).append("\\n\\n");}return text.toString().replace("\\n","\n");}
    void exportApk(String pkg)throws Exception{packageName(pkg);String paths=adb.shell("pm path "+pkg);String dir="/sdcard/Download/AstraTV-Recovery/apks/"+pkg;adb.shell("mkdir -p "+TvAdb.quote(dir));int index=0;for(String line:paths.split("\n")){if(!line.startsWith("package:"))continue;String source=line.substring(8).trim();if(!source.startsWith("/")||!source.endsWith(".apk")||source.indexOf('\0')>=0)throw new IOException("无效 APK 路径");adb.shell("cp "+TvAdb.quote(source)+" "+TvAdb.quote(dir+"/"+(index==0?"base.apk":"split-"+index+".apk")),45000);index++;}if(index==0)throw new IOException("没有找到应用安装包");}
    List<Item> importPlan(String input)throws Exception{String text=input.replace("\uFEFF","").trim();LinkedHashSet<String> names=new LinkedHashSet<>();if(text.startsWith("{")){JSONObject plan=new JSONObject(text);if(plan.has("device")&&plan.getJSONObject("device").has("ro.build.fingerprint")&&!Build.FINGERPRINT.equals(plan.getJSONObject("device").getString("ro.build.fingerprint")))throw new IOException("方案属于另一份电视固件");JSONArray entries=plan.optJSONArray("entries");if(entries==null)throw new IOException("该文件不是清理方案，请选择 debloat.txt 或 plan.json");for(int i=0;i<entries.length();i++)names.add(entries.getJSONObject(i).getString("package"));}else for(String line:text.split("\n")){String value=line.split("#",2)[0].trim();if(!value.isEmpty())names.add(value);}if(names.isEmpty())throw new IOException("清单中没有应用包名");ArrayList<Item> out=new ArrayList<>();for(String pkg:names){packageName(pkg);if(protectedPackage(pkg))throw new IOException("整份方案已拒绝：包含受保护组件 "+pkg);try{ApplicationInfo info=a.getPackageManager().getApplicationInfo(pkg,PackageManager.GET_DISABLED_COMPONENTS);out.add(new Item(pkg,a.getPackageManager().getApplicationLabel(info).toString(),"导入清单","用户导入的清单，需核对当前固件",info.enabled,false));}catch(PackageManager.NameNotFoundException ignored){}}return out;}
    public void close(){worker.shutdownNow();adb.close();}
}
